465	  }
466	
467	  protected rateSaved(rate: RateView): void {
468	    // Kept as the store lists them: in grade order, then the rate from the start, then by from-date.
469	    this.rates.update((list) => [...list.filter((r) => !sameRate(r, rate)), rate]
470	      .sort((a, b) => a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '')));
471	  }
472	
473	  protected periodAdded(period: PeriodView): void {
474	    // Kept as the store lists them: in date order.
475	    this.periods.update((list) => [...list, period].sort((a, b) => a.from.localeCompare(b.from)));
476	  }
477	
478	  protected periodChanged(period: PeriodView): void {
479	    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
480	  }
481	
482	  protected claimAdded(claim: ClaimView): void {
483	    this.claims.update((list) => [claim, ...list]);
484	  }
485	
486	  /** A quick-add's claim, and its person when the quick-add added them. */
487	  protected quickAdded(added: QuickAddView): void {
488	    if (!this.people().some((p) => p.id === added.person.id)) this.people.update((list) => [...list, added.person]);
489	    this.claimAdded(added.claim);
490	  }
491	
492	  protected claimSaved(claim: ClaimView): void {
493	    this.claims.update((list) => list.map((c) => (c.id === claim.id ? claim : c)));
494	  }
495	
496	  private reset(): void {
497	    this.editingId.set(null);
498	    this.error.set('');
499	    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
500	  }
501	
502	  protected edit(person: PersonView): void {
503	    this.personError.set(null);
504	    this.patronError.set(null);
505	    this.editingId.set(person.id);
506	    this.editingVersion.set(person.version);
507	    this.error.set('');
508	    this.form.setValue({ name: person.name, grade: person.grade }, { emitEvent: false });
509	  }
510	
511	  protected cancel(): void {
512	    this.reset();
513	  }
514	
515	  /** After an edit was refused because someone else saved the person meanwhile: re-read the people
516	   *  and show the person's current values in the editor, keeping the refusal showing. */
517	  private async showCurrent(sheetId: string, id: number): Promise<void> {
518	    try {
519	      const people = await this.api.list(sheetId);
520	      if (this.session.sheet()?.id !== sheetId) return;
521	      this.people.set(people);
522	      const current = people.find((p) => p.id === id);
523	      if (current && this.editingId() === id) {
524	        this.editingVersion.set(current.version);
525	        this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
526	      }
527	    } finally {
528	      this.error.set('Someone else has saved this person since you opened it; the form now shows their changes.');
529	    }
530	  }
531	
532	  protected async submit(): Promise<void> {
533	    // A second submit before the first has answered is ignored, so it stores one record, not two.
534	    if (this.saving()) return;
535	    const sheet = this.session.sheet();
536	    if (!sheet) return;
537	    this.error.set('');
538	    const value = this.form.getRawValue();
539	    if (!value.name.trim()) {
540	      this.error.set('Type a name for the person.');
541	      return;
542	    }
543	    if (!GRADES.includes(value.grade)) {
544	      this.error.set('Choose a grade of A, B or C.');
545	      return;
546	    }
547	    const id = this.editingId();
548	    this.saving.set(true);
549	    try {
550	      if (id === null) {
551	        const added = await this.api.add(sheet.id, { ...value, name: value.name.trim() });
552	        if (this.session.sheet()?.id === sheet.id) this.people.update((list) => [...list, added]);
553	      } else {
554	        const saved = await this.api.update(sheet.id, id,
555	          { ...value, name: value.name.trim(), version: this.editingVersion() });
556	        if (this.session.sheet()?.id === sheet.id) {
557	          this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
558	        }
559	      }
560	      if (this.session.sheet()?.id === sheet.id) this.reset();
561	    } catch (e) {
562	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
563	        await this.showCurrent(sheet.id, id);
564	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
565	        this.error.set('That name is already in use on the sheet.');
566	      } else {
567	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
568	      }
569	    } finally {
570	      this.saving.set(false);
571	    }
572	  }
573	}
